function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);
  // noLoop() removed for animation
  noStroke();
}

function draw() {
  background("#161B27");

  blendMode(LIGHTEST);
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height);
    let S = random(100, 300);
    let zoff = random(100);

    fill("#1282D7");
    drawShape(x, y, S * 0.8, 3.0, zoff);

    fill("#00B9F6");
    drawShape(x, y, S * 0.6, 4.0, zoff);

    fill("#03F2F5");
    drawShape(x, y, S * 0.4, 5.0, zoff);
  }
}

function drawShape(ox, oy, os, nm, zoff) {
  push();
  translate(ox, oy);
  beginShape();
  for (let t = 0; t < 360; t++) {
    let xoff = map(cos(t), -1, 1, 0, nm);
    let yoff = map(sin(t), -1, 1, 0, nm);

    let n = noise(xoff, yoff, zoff);

    let r = map(n, 0, 1, os * 0.25, os);
    var x = r * cos(t);
    var y = r * sin(t);

    vertex(x, y);
  }
  endShape(CLOSE);
  pop();
}
